set -Eeuo pipefail
[[ "${EUID:-$(id -u)}" == 0 ]] || { echo '[ERREUR] Lancer en root sur Batocera 44.' >&2; exit 1; }
command -v python3 >/dev/null || { echo '[ERREUR] Python3 absent.' >&2; exit 1; }
