SHA256='93ac7631f92e9002781553b6d7707b38137b789470586d77a4c2ef9b2a01ef7c'

def fail(msg): raise RuntimeError(msg)
def checksum(bs): return hashlib.sha256(bs).hexdigest()
def atomic_write(path,data,mode):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(dir=str(path.parent),prefix='.1fichier-v132-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data);f.flush();os.fsync(f.fileno())
        os.chmod(tmp,mode);os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def es_active():
    if 'BLONDIN_TEST_ROOT' in os.environ:
        return os.environ.get('BLONDIN_TEST_ES')=='1'
    for proc in Path('/proc').iterdir():
        if not proc.name.isdigit():continue
        try:
            name=(proc/'comm').read_text().strip()
            if name.startswith('emulationstat'):
                stat=(proc/'stat').read_text().rsplit(')',1)[1].split()[0]
                if stat!='Z':return True
        except (OSError,IndexError):pass
    return False

def app_active():
    if 'BLONDIN_TEST_ROOT' in os.environ:return False
    target=str(APP).encode()
    for proc in Path('/proc').iterdir():
        if not proc.name.isdigit():continue
        try:
            args=(proc/'cmdline').read_bytes().split(b'\0')
            if target in args:return True
        except (OSError,PermissionError):pass
    return False

def unpack():
    archive=base64.b64decode(PAYLOAD)
    if checksum(archive)!=SHA256:fail('Archive interne corrompue, installation annulee.')
    with tarfile.open(fileobj=io.BytesIO(archive), mode='r:gz') as tf:
        names={x.name for x in tf.getmembers()}
        expected={'app.py','port.sh','port.keys','cover.jpg','fanart.jpg','logo.png'}
        if names!=expected:fail('Fichiers internes inattendus.')
        files={name:tf.extractfile(name).read() for name in expected}
    # Conserver la reconnaissance de la v2.0 publiee, puis securiser les transferts
    # si le script d'extinction V3 n'existe pas encore sur une machine vierge.
    original_app=files['app.py']
    guard_old=(b"if TRIGGER.is_file() and MARKER not in TRIGGER.read_text(encoding='utf-8', errors='replace'):\n"
               b"        raise RuntimeError('Protection extinction absente du script actif : relancer l installateur avant toute sauvegarde.')")
    guard_new=(b"if not TRIGGER.is_file() or MARKER not in TRIGGER.read_text(encoding='utf-8', errors='replace'):\n"
               b"        raise RuntimeError('Protection extinction V3 absente : installer la protection avant toute sauvegarde.')")
    if original_app.count(guard_old)!=1:fail('Controle de securite dans app.py non reconnu.')
    KNOWN.add(checksum(original_app))
    files['app.py']=original_app.replace(guard_old,guard_new)
    compile(files['app.py'].decode('utf8'),str(APP),'exec')
    json.loads(files['port.keys'])
    for n in ('cover.jpg','fanart.jpg','logo.png'):
        if len(files[n])<1024 or not (files[n].startswith(b'\xff\xd8') if n.endswith('jpg') else files[n].startswith(b'\x89PNG\r\n\x1a\n')):
            fail('Illustration interne invalide : '+n)
    return files

def update_xml(old):
    raw=old.decode('utf-8-sig')
    root=ET.fromstring(raw)
    if root.tag!='gameList':fail('Racine gamelist inattendue.')
    accepted={FILENAME, str(PORT)}
    found=[e for e in root.findall('game') if (e.findtext('path') or '').strip() in accepted]
    if len(found)>1:fail('Plusieurs fiches 1fichier trouvees, corriger manuellement.')
    spans=[]
    for m in re.finditer(r'<game(?:\s[^>]*)?>[\s\S]*?</game\s*>',raw):
        try: node=ET.fromstring(m.group(0))
        except ET.ParseError:continue
        if (node.findtext('path') or '').strip() in accepted:spans.append((m,node))
    if len(spans)!=len(found):fail('Structure gamelist non reconnue, modification annulee.')
    if spans:node=spans[0][1]
    else:
        node=ET.Element('game')
        ET.SubElement(node,'path').text=FILENAME
    # Ne pas remplacer les informations personnalisees et statistiques.
    # Seuls les liens de visuels sont normalises; champs descriptifs ajoutes si absents.
    fields={tag:str(path) for tag,path in MEDIA.items()}
    fields.update({'name':'Sauvegarde 1fichier ★ BLONDIN EDITION ★'})
    defaults={
      'desc':('Sauvegarde 1fichier ★ BLONDIN EDITION ★ permet de lancer manuellement des sauvegardes '
        'de plusieurs dossiers vers 1fichier.com Premium, avec suivi, verification des noms et tailles, '
        'historique, navigation a la manette et protection temporaire contre l extinction.'),
      'genre':'Utilitaire / Sauvegarde', 'developer':'Blondin', 'publisher':'Blondin Edition',
      'players':'1', 'releasedate':'20261113T000000'
    }
    # Si la fiche est deja correcte, ne jamais reecrire la gamelist :
    # cela evite l'arret d'EmulationStation pour une mise a jour du moteur.
    if spans and all(node.findtext(tag)==value for tag,value in fields.items()) \
             and all(node.find(tag) is not None for tag in defaults):
        return old
    for tag,value in fields.items():
        item=node.find(tag)
        if item is None:item=ET.SubElement(node,tag)
        item.text=value
    for tag,value in defaults.items():
        item=node.find(tag)
        if item is None:ET.SubElement(node,tag).text=value
    ET.indent(node,space='    ')
    fragment=ET.tostring(node,encoding='unicode',short_empty_elements=False)
    if spans:
        m=spans[0][0];updated=raw[:m.start()]+fragment+raw[m.end():]
    else:
        end=re.search(r'</gameList\s*>',raw)
        if not end:fail('Balise fermeture gamelist introuvable.')
        updated=raw[:end.start()]+fragment+'\n'+raw[end.start():]
    tested=ET.fromstring(updated)
    expected_n=len(root.findall('game'))+(0 if spans else 1)
    if len(tested.findall('game'))!=expected_n:fail('Nombre entrees gamelist modifie!')
    test=next(x for x in tested.findall('game') if (x.findtext('path') or '').strip() in accepted)
    for tag,p in MEDIA.items():
        if test.findtext(tag)!=str(p):fail('Chemin image incorrect : '+tag)
    if spans:
        for stat in ('playcount','lastplayed','gametime'):
            if test.findtext(stat)!=spans[0][1].findtext(stat):fail('Statistique perdue : '+stat)
    return updated.encode('utf8')

lockfd=None
try:
    for p in (BASE,APP,CONF,LOCK,PORT,KEYS,GAMELIST,TRIGGER,BACKUPS,*BUNDLE.values()):
        if p.is_symlink():fail('Lien symbolique inattendu : '+str(p))
    for p in (APP,CONF):
        if p.exists() and not p.is_file():
            fail('Chemin existant non regulier : '+str(p))
    if APP.exists()!=CONF.exists():
        fail('Installation partielle : app.py et dossiers.json doivent exister ensemble; aucune donnee ecrasee.')
    fresh=not APP.is_file()
    if fresh and (PORT.exists() or KEYS.exists()):
        fail('Lanceur preexistant sans application : verifier cette installation partielle.')
    if app_active():fail('Quitter Sauvegarde 1fichier avant la mise a jour.')
    files=unpack()
    if fresh:
        folders=[]
        conf_bytes=b'[]\n'
    else:
        previous=APP.read_bytes()
        if checksum(previous) not in KNOWN|{checksum(files['app.py'])}:
            fail('Version de app.py inconnue : aucun fichier remplace. SHA256='+checksum(previous))
        conf_bytes=CONF.read_bytes()
        folders=json.loads(conf_bytes.decode('utf8'))
    if not isinstance(folders,list) or any(not isinstance(x,dict) or not all(k in x for k in ('id','nom','source','destination')) for x in folders):
        fail('dossiers.json invalide; installation refusee.')
    BASE.mkdir(parents=True,exist_ok=True)
    lockfd=os.open(LOCK,os.O_CREAT|os.O_RDWR,0o600)
    try:fcntl.flock(lockfd,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError:fail('Sauvegarde / verification en cours; mise a jour interdite.')
    original_xml=GAMELIST.read_bytes() if GAMELIST.exists() else b'<?xml version="1.0" encoding="UTF-8"?>\n<gameList>\n</gameList>\n'
    new_xml=update_xml(original_xml)
    changes={APP:files['app.py'],PORT:files['port.sh']}
    if fresh:changes[CONF]=conf_bytes
    if new_xml!=original_xml:
        if es_active():fail('EmulationStation actif : arreter ES pour mettre a jour la gamelist.')
        changes[GAMELIST]=new_xml
    if KEYS.exists():
        try:
            configured=json.loads(KEYS.read_text(encoding='utf8'))
            if not isinstance(configured,dict):fail('Configuration manette .keys invalide.')
        except ValueError:fail('Fichier .sh.keys invalide : ne pas ecraser manuellement.')
    else:changes[KEYS]=files['port.keys']
    for name,path in BUNDLE.items():
        if path.is_file():
            head=path.read_bytes()[:8]
            valid=(head.startswith(b'\xff\xd8') if name.endswith('jpg') else head.startswith(b'\x89PNG\r\n\x1a\n'))
            if not valid or path.stat().st_size<1024:fail('Illustration existante invalide : '+str(path))
        else:changes[path]=files[name]
    # Sauvegarde de tous les fichiers modifies + copies config, sans toucher aux journaux.
    backup=BACKUPS/(('installation-v2.0.1-' if fresh else 'mise-a-jour-v2.0.1-')+datetime.now().strftime('%Y%m%d-%H%M%S')+'-'+str(os.getpid()))
    backup.mkdir(parents=True,mode=0o700)
    if not fresh:(backup/'dossiers.json.bak').write_bytes(conf_bytes)
    saved={}
    for path,content in changes.items():
        saved[path]=path.read_bytes() if path.exists() else None
        if saved[path] is not None:
            name=('app.py' if path==APP else 'port.sh' if path==PORT else 'port.keys' if path==KEYS else
                  'gamelist.xml' if path==GAMELIST else path.name)
            (backup/(name+'.bak')).write_bytes(saved[path])
    installed=[]
    try:
        for path,content in changes.items():
            if saved[path]==content:continue
            mode=0o755 if path in (APP,PORT) else 0o644
            atomic_write(path,content,mode);installed.append(path)
        for path,content in changes.items():
            if path.read_bytes()!=content:fail('Verification apres installation echouee : '+str(path))
        for tag,path in MEDIA.items():
            if not path.is_file():fail('Illustration manquante : '+tag)
        if CONF.read_bytes()!=conf_bytes:fail('Configuration a change!')
    except Exception:
        for path in reversed(installed):
            old=saved[path]
            if old is None:path.unlink(missing_ok=True)
            else:atomic_write(path,old,0o755 if path in (APP,PORT) else 0o644)
        raise
    print('[OK] Sauvegarde 1fichier ★ BLONDIN EDITION ★ v2.0.1 installee.' + (' Premiere installation.' if fresh else ' Mise a jour.'))
    print('[OK] %d dossiers conserves; historique, rapports et cle API intacts.' % len(folders))
    print('[OK] Manette : Haut/Bas, A, B, Start; Gauche/Droite ignores (menu vertical).')
    print('[OK] Etat et progression : barre en direct, vitesse, ETA, fichiers et actualisation automatique.')
    print('[OK] Compte 1fichier : quota Cold Storage, abonnement et expiration (lecture seule).')
    print('[OK] Annulation manuelle avec confirmation, arret cible et historique ANNULE.')
    print('[OK] Extinction optionnelle apres succes, 30 s annulables dans le logiciel uniquement.')
    print('[OK] Quitter le suivi desactive l extinction, pas le transfert. Option NON par defaut.')
    print('[OK] Interface centree horizontalement (menus, progression, verification et saisies).')
    print('[OK] Liens de dossiers vers volumes montes: chemin reel utilise par Rclone.')
    print('[OK] Volumes externes verifiés avant et apres chaque transfert; liens internes non suivis.')
    print('[OK] Journaux individuels : bilan final colore, y compris pour les anciens journaux.')
    print('[OK] Nouveaux journaux : resultat final inscrit dans chaque fichier .log.')
    print('[OK] Ajout de dossier : /userdata/roms/ pre-rempli, chemin entierement editable.')
    print('[OK] Menu principal 5 rubriques : Sauvegardes, Dossiers, Progression, Controles, Compte.')
    print('[OK] Annulation rapide 9 affichee uniquement durant un transfert.')
    print('[OK] Verification : progression, manquants, tailles differentes et bilan historique.')
    print('[OK] Images: image=fanart, cover=boxart, logo=marquee (singulier).')
    print('[OK] Rclone, protection extinction V3 et ntfy inchanges. Aucun transfert lance.')
    if not TRIGGER.is_file() or MARK not in TRIGGER.read_text(encoding='utf8',errors='replace'):
        print('[ATTENTION] Garde extinction V3 absent : les transferts resteront bloques.')
    if fresh:
        print('[INFO] Configurer le remote Rclone 1fichier: et ajouter les dossiers dans le menu.')
    print('[OK] Copie securite : '+str(backup))
    if GAMELIST in changes:print('[INFO] Gamelist actualisee : redemarrer Batocera completement.')
    else:print('[INFO] Gamelist deja correcte : relancer simplement le Port.')
except Exception as exc:
    print('[ERREUR] '+str(exc),file=sys.stderr);sys.exit(1)
finally:
    if lockfd is not None:
        try:fcntl.flock(lockfd,fcntl.LOCK_UN)
        finally:os.close(lockfd)
